using SeedCsharpOauthTokenRequiredGrantType;

var client = new SeedCsharpOauthTokenRequiredGrantTypeClient(
    clientOptions: new ClientOptions { ClientId = "client_id", ClientSecret = "client_secret" }
);
await client.Auth.CreateOauth2TokenAsync(
    new CreateOauth2TokenRequest
    {
        ClientId = "my_oauth_app_123",
        ClientSecret = "sk_live_abcdef123456789",
        GrantType = "client_credentials",
    }
);
